import React from 'react';
import './Footer.css';

const Footer = () => {
    return (
        <footer className="footer">
            <div className="footer-content">
                <p>&copy; {new Date().getFullYear()} Recordar para defender la democracia. Todos los derechos reservados.</p>
                <div className="footer-links">
                    <a href="#inicio">Inicio</a>
                    <a href="#contexto-historico">Contexto Histórico</a>
                    <a href="#linea-de-tiempo">Línea de Tiempo</a>
                    <a href="#importancia">¿Por qué importa hoy?</a>
                    <a href="#propuesta-innovadora">Propuesta Innovadora</a>
                    <a href="#publico-objetivo">Público Objetivo</a>
                    <a href="#triple-helice">Triple Hélice</a>
                    <a href="#cuadruple-helice">Cuádruple Hélice</a>
                    <a href="#aporte-desarrollo">Aporte al Desarrollo</a>
                    <a href="#aprendizajes">Aprendizajes</a>
                    <a href="#conclusion">Conclusión</a>
                </div>
            </div>
        </footer>
    );
};

export default Footer;
